def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    # Endgame: always defect on the final round
    if n >= 99:
        return 'D'

    # If opponent has never cooperated, defect always
    if opp_c == 0:
        if n >= 4:
            return 'D'
        if n >= 1 and opp[-1] == 'D':
            return 'D'
        return 'C'

    # If opponent is mostly defective, defect always
    if opp_c * 5 < n:
        return 'D'

    # If opponent is very cooperative, cooperate but exploit near the end
    if opp_c * 5 > n * 4:
        if opp[-1] == 'D':
            if n >= 2 and opp[-2] == 'D':
                # Break out of a long mutual defection loop
                recent_dd = 0
                for i in range(max(0, n-5), n):
                    if history[i][0] == 'D' and history[i][1] == 'D':
                        recent_dd += 1
                if recent_dd >= 3 and rng.random() < 0.5:
                    return 'C'
                return 'D'
            return 'C'
        # Near the end, defect more often to exploit unconditional cooperators
        if n >= 95:
            if rng.random() < 0.8:
                return 'D'
        if n >= 90:
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # Main regime: forgiving tit-for-tat with a break-out mechanism
    if opp[-1] == 'D':
        if n >= 2 and opp[-2] == 'D':
            recent_dd = 0
            for i in range(max(0, n-5), n):
                if history[i][0] == 'D' and history[i][1] == 'D':
                    recent_dd += 1
            if recent_dd >= 3 and rng.random() < 0.5:
                return 'C'
            return 'D'
        return 'C'
    else:
        # Opponent cooperated. If we just defected, cooperate to restore.
        if me[-1] == 'D':
            return 'C'
        return 'C'
